INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Malaysia';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (MyInvois)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. MyInvois validation rules, phase thresholds, and penalty provisions continue to evolve — confirm current requirements directly with LHDN before building an integration.', 'Malaysia''s rollout works top-down by turnover tier, with a relaxation period running well past each tier''s formal start date.', 'Malaysia genuinely supports two serialisations of the same underlying UBL 2.1 structure — pick whichever fits your stack, not a fixed single format.', 'MyInvois is a genuine clearance platform: LHDN validates in real time and assigns identifiers before an invoice carries legal weight.', 'Getting API credentials is a genuine multi-step identity-verification process, not a self-serve signup.', 'Non-compliance ties back into Malaysia''s general Income Tax Act framework rather than a standalone e-invoicing fine schedule.' FROM countries WHERE name_en = 'Malaysia';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Malaysia';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'UBL 2.1', 'XML or JSON');
