INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Malaysia';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'Validation lifecycle', NULL, 'On successful validation, MyInvois returns a UUID immediately and a Long ID once server-side validation completes — build your status polling around both identifiers.');
